    },
    {
      "id": "ranking",
      "critical": true,
      "status": "pass",
      "expected": "United States",
      "actual": "United States",
      "evidence": ["final-answer.txt：“2023 年最高者：美国，约 14.3 t CO₂/人”"],
      "reason": "正确指出美国为 2023 年人均排放最高者。"
    },
    {
      "id": "estimates",
      "critical": true,
      "status": "pass",
      "expected": "约／approximately",
      "actual": "首段明确为估读约数，表格各数值及净变化均标注“约”。",
      "evidence": ["final-answer.txt：首段、国家数值表及末段"],
      "reason": "没有将读图结果声称为精确统计值。"
